// Review comments on nodes and lines: kept in browser storage, exported as export-comment.md for the agent.
import { doorAnchor, type Model } from "../model/model";

export const EXPORT_NAME = "export-comment.md";
export const EXPORT_HEADER =
  "<!-- Generated by the visualizing-codebases skill (the viewer, by you); review comments and pin changes exported from the viewer, for the agent to read. Do not edit: the next run overwrites it. -->";

export interface Comment {
  target: string;          // node id, group id, or bundle key "a|b"
  text: string;
  at: string;              // ISO time
}

export interface Store {
  getItem(k: string): string | null;
  setItem(k: string, v: string): void;
}

export class Comments {
  private key: string;
  private list: Comment[] = [];

  constructor(private model: Model, private store: Store | null) {
    this.key = `viz-code:comments:${model.map.meta.repo}`;
    try {
      const raw = store?.getItem(this.key);
      const stored = raw ? JSON.parse(raw) : [];
      this.list = Array.isArray(stored) ? stored.filter((c) => c && typeof c.target === "string" && typeof c.text === "string") : [];
    } catch {
      this.list = [];
    }
  }

  all(): Comment[] {
    return [...this.list];
  }

  for(target: string): Comment[] {
    const key = norm(target, this.model);
    return this.list.filter((c) => c.target === key);
  }

  add(target: string, text: string, now = new Date()): void {
    const t = text.trim();
    if (!t) return;
    this.list.push({ target: norm(target, this.model), text: t, at: now.toISOString() });
    this.save();
  }

  /** Delete one note (as returned by `for` or `all`). */
  drop(c: Comment): void {
    const i = this.list.indexOf(c);
    if (i >= 0) this.remove(i);
  }

  remove(index: number): void {
    this.list.splice(index, 1);
    this.save();
  }

  clear(): void {
    this.list = [];
    this.save();
  }

  /** Comments whose node or line no longer exists in this map. */
  orphaned(): Comment[] {
    return this.list.filter((c) => !this.exists(c.target));
  }

  private exists(raw: string): boolean {
    const target = norm(raw, this.model);   // comments saved before door ids were normalised
    if (target.includes("|") && !this.model.nodes.has(target)) return target.split("|").every((x) => this.exists(x));
    return this.model.nodes.has(target) || this.model.groups.has(target) || target === "site";
  }

  private save() {
    try {
      this.store?.setItem(this.key, JSON.stringify(this.list));
    } catch {
      /* storage unavailable: comments live for this page only */
    }
  }

  /** Markdown for the agent: grouped by service, each block self-contained. */
  toMarkdown(): string {
    const m = this.model;
    const meta = m.map.meta;
    const lines = [
      EXPORT_HEADER,
      "",
      `# Review comments — ${meta.repo} @ ${meta.commit.slice(0, 12)}`,
      "",
      "Comments a reviewer left on the code map. Each block names the node (or the line between two nodes),",
      "where it lives in the code, and what the reviewer wants. Treat them as review feedback: fix the code,",
      "then rescan so the map stays current.",
      "",
      `Paths are relative to ${meta.root ? `the folder \`${meta.root}\` of the repository` : "the repository root"}: ` +
        `read a file at the map commit with \`git -C REPO show ${meta.commit.slice(0, 12)}:./<path>\`.`,
      "",
    ];
    const serviceOf = (id: string): string => {
      const first = id.split("|")[0];
      const path = m.path(m.floorOf(first) ?? "site");
      return path[1] ?? (m.nodes.get(first)?.parent ? "site" : first);
    };
    const groups = new Map<string, Comment[]>();
    for (const c of this.list) groups.set(serviceOf(c.target), [...(groups.get(serviceOf(c.target)) ?? []), c]);
    for (const [svc, list] of [...groups.entries()].sort()) {
      lines.push(`## ${svc === "site" ? "Whole system" : m.label(svc)}`, "");
      for (const c of list) {
        const ends = c.target.includes("|") && !m.nodes.has(c.target) ? c.target.split("|") : [c.target];
        const title = ends.map((id) => `${m.label(id)} (${m.codes.get(id) ?? "?"})`).join(" ↔ ");
        lines.push(`### ${title}`, "");
        for (const id of ends) {
          const n = m.nodes.get(id);
          const where = n?.file ? `${n.file}${n.line ? ":" + n.line : ""}` : "—";
          lines.push(`- node: \`${id}\` · kind: ${m.kindOf(id)} · at: \`${where}\``);
        }
        if (!this.exists(c.target)) lines.push("- **orphaned**: this node is not in the current map (renamed or removed)");
        lines.push(`- map commit: \`${meta.commit}\` · commented: ${c.at}`, "", c.text, "");
      }
    }
    if (!this.list.length) lines.push("_No comments._", "");
    return lines.join("\n");
  }
}

/** Save into the map's folder where the browser allows it (Chromium), else download. */
export async function saveExport(markdown: string, win: Window & typeof globalThis = window): Promise<"saved" | "downloaded" | "cancelled"> {
  const picker = (win as unknown as { showDirectoryPicker?: (o?: object) => Promise<FileSystemDirectoryHandle> }).showDirectoryPicker;
  if (picker) {
    try {
      const dir = await picker.call(win, { id: "viz-code", mode: "readwrite" });
      const file = await dir.getFileHandle(EXPORT_NAME, { create: true });
      const w = await file.createWritable();
      await w.write(markdown);
      await w.close();
      return "saved";
    } catch (e) {
      if ((e as DOMException)?.name === "AbortError") return "cancelled";
    }
  }
  const url = URL.createObjectURL(new Blob([markdown], { type: "text/markdown" }));
  const a = win.document.createElement("a");
  a.href = url;
  a.download = EXPORT_NAME;
  a.click();
  URL.revokeObjectURL(url);
  return "downloaded";
}

/** A line to a door is the line to the node the door stands for, and a twin is its package: store and export
 *  the real ids, not `door:` or `twin:`. */
function norm(target: string, model?: Model): string {
  return target.split("|").map((x) => {
    const y = doorAnchor(x);
    return model?.twinOf(y) ?? y;   // a twin is the package it stands for
  }).join("|");
}
